    uint received;
    constructor(C _c) { c = _c; }
    function run(uint a, uint b) public payable {
        require(address(this).balance >= a + b);
        // first cycle: deposit a and withdraw it
        c.deposit{value: a}();
        uint balBefore1 = address(c).balance;
        c.withdrawAll();
        uint balAfter1 = address(c).balance;
        // credit must be fully reset: C balance decreased by exactly a
        // second independent cycle: deposit b and withdraw it
        c.deposit{value: b}();
        uint balBefore2 = address(c).balance;
        received = 0;
        c.withdrawAll();
        uint balAfter2 = address(c).balance;
        assert(balBefore1 == a && balAfter1 == 0 && received == b && balAfter2 == 0 && balBefore2 == b);
    }
    receive() external payable { received += msg.value; }
}

